/// Окончания строк файла V5.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum V5Eol {
    Lf,
    CrLf,
    Cr,
    /// LF, CRLF и CR по очереди.
    Mixed,
}

/// Файл корпуса: имя в [`v5_dir`](crate::v5_dir), кодировка (метка WHATWG, как у
/// `encoding_rs`), BOM, окончания строк и точный текст после декодирования (без BOM).
#[derive(Copy, Clone, Debug)]
pub struct V5Case {
    pub file: &'static str,
    pub encoding: &'static str,
    pub bom: bool,
    pub eol: V5Eol,
    pub text: &'static str,
}

